"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["35995"],{57207(e){e.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.obrigatoriedade_legal.nao_encontrada","status":404,"titulo":"ObrigatoriedadeLegal n\xe3o encontrada"},"descricao":{"codigo":"uniplus.selecao.obrigatoriedade_legal.nao_encontrada","requisitos":[],"oQueAconteceu":["O identificador da rota n\xe3o corresponde a nenhuma obrigatoriedade legal ativa. A mensagem da\\nresposta traz o identificador informado. Nada \xe9 alterado.","Regra j\xe1 desativada tamb\xe9m n\xe3o \xe9 encontrada: a desativa\xe7\xe3o retira a regra das opera\xe7\xf5es de\\natualiza\xe7\xe3o e de nova desativa\xe7\xe3o. Por isso repetir a desativa\xe7\xe3o de uma regra devolve este erro na\\nsegunda tentativa.","Na atualiza\xe7\xe3o, a regra \xe9 buscada depois de os campos do corpo serem conferidos pelas regras do\\ndom\xednio, cujas recusas t\xeam status 422 e c\xf3digo pr\xf3prio por campo (por exemplo,\\n[`regra_codigo_obrigatorio`](/erros/uniplus.selecao.obrigatoriedade_legal.regra_codigo_obrigatorio)\\ne\\n[`vigencia_inicio_obrigatorio`](/erros/uniplus.selecao.obrigatoriedade_legal.vigencia_inicio_obrigatorio)),\\ne antes de qualquer confer\xeancia que consulte cadastros, como a do tipo de processo\\n([`tipo_processo_nao_encontrado_ou_inativo`](/erros/uniplus.selecao.obrigatoriedade_legal.tipo_processo_nao_encontrado_ou_inativo)).\\nV\xeam antes de tudo a permiss\xe3o para manter obrigatoriedades legais e a leitura do corpo da requisi\xe7\xe3o,\\nque recusa com status 400 o JSON ileg\xedvel e o corpo ausente, e a confer\xeancia de que o identificador do\\ncorpo \xe9 o da rota, que tamb\xe9m recusa com status 400 (`uniplus.contract.id_path_body_divergente`).","Se os campos de uma atualiza\xe7\xe3o estiverem incorretos, a resposta indica o erro de campo mesmo quando a regra n\xe3o existe. Isso tamb\xe9m vale para um identificador composto de zeros na rota e no corpo: com os campos corretos, a resposta \xe9 esta; caso contr\xe1rio, \xe9 a recusa do campo. A desativa\xe7\xe3o n\xe3o recebe corpo e responde este erro diretamente.","A consulta p\xfablica de uma regra por identificador n\xe3o usa este c\xf3digo."],"comoResolver":["Confira o identificador na listagem de obrigatoriedades legais; use `vigentes=false`, porque sem\\nesse par\xe2metro a listagem traz s\xf3 as regras vigentes na data de hoje. Se a regra foi desativada e deve\\nvoltar a valer, cadastre-a de novo: o c\xf3digo de uma regra desativada fica livre para uso."],"ondeAparece":["Atualiza\xe7\xe3o de uma obrigatoriedade legal","Desativa\xe7\xe3o de uma obrigatoriedade legal"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Obrigatoriedade legal"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"3bbcc2307827ee8c6dab135295710bb856847f61"}}')}}]);